<div class="container-fluid py-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="mb-1"><i class="bi bi-diagram-3 me-2"></i>Network Map</h3><small class="text-muted">Router and customer topology</small></div><span class="badge bg-success">{{ $routers->count() }} routers online</span></div><div class="row g-3 mb-3"><div class="col-md-3"><div class="card"><div class="card-body"><small>Active Customers</small><h4>{{ number_format($customers) }}</h4></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Map Nodes</small><h4>{{ number_format($nodes->count()) }}</h4></div></div></div><div class="col-md-6"><div class="card"><div class="card-body"><small>Connected Routers</small><div class="d-flex gap-2 flex-wrap mt-2">@forelse($routers as $r)<span class="badge bg-light text-dark border">{{ $r->router_name }}</span>@empty<span class="text-muted">No connected routers</span>@endforelse</div></div></div></div></div><div class="card"><div id="network-map" style="height:620px;border-radius:.5rem"></div></div><script>document.addEventListener('livewire:navigated',()=>{if(!window.L){const s=document.createElement('script');s.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';document.head.appendChild(s);s.onload=()=>window.initNetworkMap?.();}else window.initNetworkMap?.();});window.initNetworkMap=()=>{const el=document.getElementById('network-map');if(!el||el._map)return;const map=L.map(el).setView([23.8103,90.4125],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const nodes=@json($nodes);nodes.forEach(n=>L.circleMarker([n.lat,n.lng],{radius:7}).bindPopup('<strong>'+((n.label||n.id)+'').replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</strong><br><a href="/customer?search='+encodeURIComponent(n.id)+'">View Customer</a>',{maxWidth:260}).addTo(map));setTimeout(()=>map.invalidateSize(),200);};</script><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"></div>